def strategy(history, rng):
    if not history:
        return 'C'
    n = len(history)
    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    opp_c = sum(1 for a in opp if a == 'C')
    me_c = sum(1 for a in me if a == 'C')
    last_me, last_opp = history[-1]

    # Endgame: with payoff DC=5 > CC=3, defect in last few rounds unless opponent likely punishing
    remaining = 100 - n
    if remaining <= 1:
        return 'D'
    if remaining <= 3:
        # defect if opponent defected recently
        recent_opp_d = any(a == 'D' for a in opp[-4:])
        return 'D' if recent_opp_d else 'C'

    # Detect pure defectors / very defection-heavy opponents
    if n >= 8:
        if opp_c == 0:
            return 'D'
        if opp_c <= n * 0.15 and n >= 12:
            return 'D'

    # Detect pure cooperators / very cooperative: exploit cautiously but keep them cooperating
    if n >= 6:
        if opp_c == n:
            # exploit occasionally - defect sometimes to grab 5, but not too often
            if n >= 10 and (n % 5 == 0):
                return 'D'
            return 'C'

    # Compute recent opponent cooperation rate
    lookback = min(n, 12)
    recent_opp = opp[-lookback:]
    recent_opp_c = sum(1 for a in recent_opp if a == 'C')
    recent_rate = recent_opp_c / lookback

    # Long-run opponent cooperation
    total_rate = opp_c / n

    # If opponent has been defecting a lot, retaliate but probe occasionally
    if recent_rate < 0.25:
        # punish: defect, but occasionally offer olive branch
        if n % 7 == 0:
            return 'C'
        return 'D'

    if recent_rate < 0.5:
        # mixed: mirror last opponent action with slight forgiveness
        if last_opp == 'D':
            # forgive once in a while
            if rng.random() < 0.15:
                return 'C'
            return 'D'
        return 'C'

    # Opponent mostly cooperates: cooperate, but test/exploit occasionally
    if recent_rate >= 0.85:
        # occasionally defect to gain 5 while keeping them nice
        if n % 9 == 0 and n > 5:
            return 'D'
        return 'C'

    # Moderate cooperation: tit-for-tat with forgiveness + occasional probe
    if last_opp == 'D':
        if rng.random() < 0.1:
            return 'C'
        return 'D'
    if last_me == 'D' and last_opp == 'C':
        # I defected and they cooperated - maybe continue exploiting slightly
        if rng.random() < 0.3 and recent_rate > 0.6:
            return 'D'
    return 'C'

